<template>
  <section class="role-section">
    <header><p class="eyebrow">Procurement</p><h2>Purchasing and deliveries</h2><p>Track purchase orders, their current stage, and expected delivery dates.</p></header>
    <div class="metric-grid"><article v-for="metric in metrics" :key="metric.label" class="metric"><span>{{ metric.label }}</span><strong>{{ metric.value }}</strong><small>{{ metric.note }}</small></article></div>
    <div class="panel-grid"><article class="panel"><h3>Order calendar · this month</h3><div class="calendar"><span v-for="day in weekdays" :key="day" class="weekday">{{ day }}</span><span v-for="cell in calendarCells" :key="cell.key" class="day" :class="{ muted: !cell.inMonth, marked: cell.count }"><b>{{ cell.day }}</b><small v-if="cell.count">{{ cell.count }} due</small></span></div></article><article class="panel"><h3>Recent purchase orders</h3><div v-if="recentOrders.length" class="table-wrap"><table><thead><tr><th>Order</th><th>Supplier</th><th>Status</th><th>Expected</th></tr></thead><tbody><tr v-for="item in recentOrders" :key="item.id"><td>{{ item.poNumber || item.orderNumber || item.id }}</td><td>{{ item.supplierName || 'Supplier' }}</td><td>{{ item.status || 'In progress' }}</td><td>{{ expectedDate(item) }}</td></tr></tbody></table></div><p v-else class="empty">No purchase orders to display.</p></article></div>
  </section>
</template>
<script setup>
import { computed } from 'vue'
const props = defineProps({ orders: { type: Array, default: () => [] } })
const month = new Date()
const weekdays = ['S', 'M', 'T', 'W', 'T', 'F', 'S']
const dateKey = date => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
const expectedDate = item => item.expectedDeliveryDate || item.deliveryDate || item.expectedDate || '—'
const metrics = computed(() => [{ label: 'Open orders', value: props.orders.filter(item => !['completed', 'cancelled', 'received'].includes(String(item.status || '').toLowerCase())).length, note: 'Awaiting completion' }, { label: 'Awaiting delivery', value: props.orders.filter(item => /approved|sent|confirmed|delivery|progress/i.test(String(item.status || ''))).length, note: 'Active purchase orders' }, { label: 'Orders this month', value: props.orders.filter(item => String(item.createdAt?.toDate?.()?.toISOString?.() || item.createdAt || item.createdDate || '').slice(0, 7) === dateKey(month).slice(0, 7)).length, note: month.toLocaleDateString(undefined, { month: 'long' }) }])
const recentOrders = computed(() => [...props.orders].sort((a, b) => String(b.createdAt?.toDate?.()?.toISOString?.() || b.createdAt || '').localeCompare(String(a.createdAt?.toDate?.()?.toISOString?.() || a.createdAt || ''))).slice(0, 8))
const calendarCells = computed(() => { const first = new Date(month.getFullYear(), month.getMonth(), 1); const start = new Date(month.getFullYear(), month.getMonth(), 1 - first.getDay()); return Array.from({ length: 35 }, (_, index) => { const date = new Date(start); date.setDate(start.getDate() + index); const key = dateKey(date); const count = props.orders.filter(item => expectedDate(item) === key).length; return { key, day: date.getDate(), inMonth: date.getMonth() === month.getMonth(), count } }) })
</script>
<style scoped>
.role-section{display:grid;gap:1rem;color:#4a3324}.role-section header h2{margin:.25rem 0;font:600 1.65rem Georgia,serif;color:#402719}.role-section header p:last-child{margin:.3rem 0;color:#806b5a}.eyebrow{margin:0;color:#91643f;font-size:.68rem;font-weight:700;letter-spacing:.18em;text-transform:uppercase}.metric-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:.8rem}.metric,.panel{min-width:0;border:1px solid #ead8c2;border-radius:1rem;background:#fffdf9;padding:1rem;box-shadow:0 8px 24px #4b311e0a}.metric span,.metric small{display:block;color:#806b5a;font-size:.8rem}.metric strong{display:block;margin:.45rem 0;color:#4a2d1c;font-size:1.7rem}.panel-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,340px),1fr));gap:1rem}.panel h3{margin:0 0 .8rem;color:#4a2d1c;font-size:1rem}.calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:.3rem}.weekday{text-align:center;color:#806b5a;font-size:.7rem;font-weight:700}.day{display:flex;min-height:48px;flex-direction:column;justify-content:space-between;border:1px solid #efe3d5;border-radius:.5rem;padding:.35rem;color:#513722;font-size:.75rem}.day.marked{border-color:#bc9575;background:#f8efe5}.day small{color:#91643f;font-size:.62rem}.day.muted{opacity:.42}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:.82rem}th,td{padding:.65rem .5rem;border-bottom:1px solid #efe3d5;white-space:nowrap}th{color:#806b5a;font-size:.7rem;text-transform:uppercase;letter-spacing:.06em}.empty{color:#806b5a;font-size:.85rem}@media(max-width:600px){.role-section header h2{font-size:1.4rem}.day{min-height:40px;padding:.25rem}.day small{font-size:.55rem}th,td{padding:.55rem .4rem;font-size:.75rem}}
</style>
